// Every PDF generated here MUST carry the legal disclaimer and ~57% axe-core coverage
// disclosure. CLAUDE.md Hard Rule 5 & 6 — enforced via DISCLAIMER_BODY constant below.
// FORBIDDEN language anywhere in this file: "ADA compliant", "lawsuit-proof", "certified accessible"

import { PDFDocument, StandardFonts, rgb, type PDFFont, type PDFPage } from 'pdf-lib'

// ─── Legal compliance constants ───────────────────────────────────────────────
const DISCLAIMER_BODY =
  'This document is not legal advice. It is a technical assessment generated by ' +
  'automated tooling. Consult a qualified attorney for legal guidance. This scan ' +
  'uses axe-core, which identifies approximately 57% of WCAG 2.1 accessibility ' +
  'issues per Deque Systems research. Manual testing is required for full ' +
  'compliance assessment.'

const FOOTER_NOTICE = 'Not legal advice  |  axe-core ~57% WCAG coverage  |  Consult a qualified attorney'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ViolationSummary {
  id: string
  description: string
  impact: 'critical' | 'serious' | 'moderate' | 'minor' | null
  nodes_affected: number
  wcag_criteria: string[]
}

export interface EnhancedViolation {
  originalId:     string
  plainEnglish:   string
  businessImpact: string
  fixDifficulty:  'Easy' | 'Medium' | 'Hard'
  estimatedTime:  string
}

export interface EvidenceData {
  url: string
  businessName?: string | null
  scanDate: Date
  score: number
  tier: 'basic' | 'premium' | 'monitoring'
  violations: ViolationSummary[]
  enhancedViolations?: EnhancedViolation[]
  passCount: number
  incompleteCount: number
}

export interface MonitoringData {
  url: string
  activationDate: Date
  email: string
}

// ─── Remediation hints (dev guide) ───────────────────────────────────────────

